import type { LedgerRow, PanelSubtitlePart } from "../common/Card";
import { FRANCHISE_KEY } from "../common/filterSchema";
import { ledgerParts, linked } from "../common/ledgerRow";
import { seriesRow } from "../common/series";
import type { FranchiseEntry } from "../common/franchiseUnion";
import type { MediumSpan } from "../common/medium";
import type { ReactNode } from "react";
import { formatDate } from "../common/date";
import { certificateToColour, franchiseToColour, genreToColour, mediumFills, type Scheme } from "../utils/types";
import { movieItemKey } from "./statsData";
import type { Movie } from "./types";

/**
 * How a film is named wherever it is promoted: who directed it, then the genre, wearing the
 * swatch its ledger row and every genre wedge on the tab wear.
 *
 * Shared rather than assembled at each site, so the hero, the hover card and the Omnibus's Now
 * card cannot come to name one film two ways.
 */
export const movieSubtitle = (movie: Movie, scheme: Scheme): PanelSubtitlePart[] => [
  { text: movie.director },
  { text: movie.genre, swatch: genreToColour(movie.genre, scheme) },
];

/**
 * The facts that are not figures.
 *
 * A row carries a swatch exactly where the app speaks that field's colour somewhere else — the
 * genre shares the shows tab's vocabulary, the certificate the games tab's map.
 */
export const movieRows = (movie: Movie, scheme: Scheme): LedgerRow[] => {
  const rows: LedgerRow[] = [
    { label: "Watched", value: formatDate(movie.startDate) },
    { label: "Released", value: formatDate(movie.releaseDate) },
  ];

  rows.push(
    { label: "By", ...linked("director", movie.director) },
    // The primary genre leads and the rest follow it, which is the order the sheet holds them in
    // and the order the charts group by.
    {
      label: "Genre",
      // The primary genre alone is what the tab narrows by, so it leads to its layer and the rest
      // stand as words.
      ...ledgerParts([{ text: movie.genre, category: "genre" }, ...movie.otherGenres.map((text) => ({ text }))]),
      swatch: genreToColour(movie.genre, scheme),
    },
    {
      label: "BBFC",
      ...linked("certificate", movie.certificate),
      swatch: certificateToColour(movie.certificate, scheme),
    },
  );

  const series = seriesRow(movie);
  if (series) rows.push(series);

  // Every film stands in a franchise, a standalone in one of its own name, and the row is the way to its
  // page either way. Unknown franchises fall through to an empty colour, which is no swatch
  // rather than a black one — the table names the couple of dozen the app draws.
  rows.push({
    label: "Franchise",
    ...linked(FRANCHISE_KEY, movie.franchise),
    swatch: franchiseToColour(movie, scheme) || undefined,
  });

  return rows;
};

/**
 * When a film ran, for any scale that places it: a point — `start === end` — which every strip
 * floors to its own minimum band width and draws as a dot. Being watched is the whole of a film,
 * so its watch date is both ends of it and there is nothing for the span to run to.
 */
export const movieSpan = (movie: Movie): MediumSpan => ({
  start: movie.startDate,
  end: movie.startDate,
});

/**
 * A film in a franchise strip's vocabulary. One mapper for the tab's own index and the union.
 */
export const movieEntry = (movie: Movie, hoverCard: () => ReactNode): FranchiseEntry => ({
  key: movieItemKey(movie),
  subject: movieItemKey(movie),
  franchise: movie.franchise,
  medium: "movie",
  fill: mediumFills.movie,
  label: movie.name,
  ...movieSpan(movie),
  hoverCard,
});
