import { formatDateRange, type YearMonthDay } from "../common/date";
import { FRANCHISE_KEY } from "../common/filterSchema";
import { ledgerParts, linked } from "../common/ledgerRow";
import type { LedgerRow, PanelSubtitlePart } from "../common/Card";
import type { StripSpan } from "../common/timelineStripData";
import type { FranchiseEntry } from "../common/franchiseUnion";
import { spanUntil } from "../common/medium";
import type { ReactNode } from "react";
import { certificateToColour, franchiseToColour, genreToColour, mediumFills, type Scheme } from "../utils/types";
import { lastWatchedSeason } from "./statsData";
import { finishedKey, type FinishedItem, type FinishedSplit } from "../common/finishedData";
import { networkToColour, seasonArtwork, type Season, type Show } from "./types";
import "../utils/arrayUtils";

interface SeasonSpan extends StripSpan {
  season: Season;
}

/**
 * The strip key carries the show's name as well as the season number, because a franchise strip
 * draws several shows' seasons side by side and every one of them has an S1.
 */
export const spanKey = (season: Season) => `${season.show.name}-S${season.s}`;

/**
 * The same pair under the medium's name, which is what identifies a season among the union of the
 * four libraries: the key the Omnibus keys the season's row on, and the one a franchise strip
 * draws it under, so the two cannot come to disagree.
 */
export const seasonKey = (season: Season) => `show-${spanKey(season)}`;

/**
 * What a show's card looks for on a franchise strip. The strip's entries are seasons, and the card
 * is the show's, so every season of it answers the show rather than itself.
 */
export const showSubject = (show: Show) => `show-${show.name}`;

/**
 * Every season of every show given, as spans for `buildStrip`. A season still being watched runs
 * to `today`, which is what an open bar on the full timeline means too.
 */
export const seasonSpans = (shows: Show[], today: YearMonthDay): SeasonSpan[] =>
  shows
    .flatMap((show) => show.s)
    .map((season) => ({
      key: spanKey(season),
      start: season.startDate,
      end: season.endDate ?? today,
      season,
    }));

/**
 * How a show is named wherever it is promoted: the network it's on, then the genre, wearing the
 * swatch its ledger row and every genre wedge on the tab wear.
 *
 * Shared rather than assembled at each site, so the hero, the hover card and the Omnibus's Now
 * card cannot come to name one show two ways.
 */
export const showSubtitle = (show: Show, scheme: Scheme): PanelSubtitlePart[] => [
  { text: show.network },
  { text: show.genre, swatch: genreToColour(show.genre, scheme) },
];

/**
 * The facts that are not figures.
 *
 * A row carries a swatch exactly where the app speaks that field's colour somewhere else — the
 * certificate shares the games tab's map, the genre the vocabulary Movies shares, the network its own
 * table where it has an entry. Status has a colour too and is already a filled tile above, so
 * repeating it here would say it twice.
 */
export const showRows = (show: Show, scheme: Scheme): LedgerRow[] => {
  const lastWatched = lastWatchedSeason(show);
  const rows: LedgerRow[] = [
    { label: "Watched", value: formatDateRange(show.startDate, show.endDate) },
    // The season the hero would name for this show, not the last one listed: a show whose newest
    // season the sheet has not dated yet was last watched in the one before it, and a ledger
    // disagreeing with the hero above it about that is two answers to one question. Its own
    // number, not its position — the sheet lists only the seasons watched, so a show picked up at
    // S5 holds fewer entries than its numbering.
    { label: "Last Watched", value: `S${lastWatched.s}E${lastWatched.e}` },
    // The primary genre leads and the rest follow it, which is the order the sheet holds them in
    // and the order the charts group by.
    {
      label: "Genre",
      // The primary genre alone is what the tab narrows by, so it leads to its layer and the rest
      // stand as words.
      ...ledgerParts([{ text: show.genre, category: "genre" }, ...show.otherGenres.map((text) => ({ text }))]),
      swatch: genreToColour(show.genre, scheme),
    },
    {
      label: "Network",
      ...linked("network", show.network),
      swatch: networkToColour(show, scheme) || undefined,
    },
    {
      label: "BBFC",
      ...linked("certificate", show.certificate),
      swatch: certificateToColour(show.certificate, scheme),
    },
  ];

  // The runtime of the most recent season's episodes — where the seasons disagree, the latest is
  // the one a reader deciding whether to start tonight is asking about. The latest *with* a
  // runtime: an open season the sheet has no length for yet is exactly the one the hero names,
  // and its card would otherwise lose the row its three earlier seasons all carry.
  const episodeLength = show.s.findLast((season) => season.episodeLength)?.episodeLength;
  if (episodeLength) rows.push({ label: "Episode", value: `${episodeLength} min` });

  // Every show stands in a franchise, a standalone in one of its own name, and the row is the way to its
  // page either way. Unknown franchises fall through to an empty colour, which is no swatch
  // rather than a black one — the table names the couple of dozen the app draws.
  rows.push({
    label: "Franchise",
    ...linked(FRANCHISE_KEY, show.franchise),
    swatch: franchiseToColour(show, scheme) || undefined,
  });

  return rows;
};

/**
 * A season in a franchise strip's vocabulary. Every season answers its show as its subject, so a
 * card's own show is every one of its seasons and a sibling show's are context. One mapper for the
 * tab's own index and the union, so the two cannot draw the same season two ways.
 */
export const seasonEntry = (season: Season, today: YearMonthDay, hoverCard: () => ReactNode): FranchiseEntry => ({
  key: seasonKey(season),
  subject: showSubject(season.show),
  franchise: season.show.franchise,
  medium: "show",
  fill: mediumFills.show,
  label: `${season.show.name} S${season.s}`,
  ...spanUntil(season, today),
  hoverCard,
});

/**
 * A card in the tab's library: a whole show, or one season of it under the Seasons count.
 *
 * A wrapper rather than the model itself, because a season carries no name, franchise or artwork
 * of its own for the wall to sort and shelve it by, and both counts have to be one type for the
 * one wall to hold either.
 */
export interface ShowShelfItem extends FinishedItem {
  /** The show's, carried so the genre shelf every tab shares reads it as it reads any other wall. */
  genre: string;
  show: Show;
  season?: Season;
}

/** A show as the library's card for the whole of it, standing where the show's own dates put it. */
export const showShelfItem = (show: Show): ShowShelfItem => ({
  name: show.name,
  franchise: show.franchise,
  genre: show.genre,
  artwork: show.artwork,
  startDate: show.startDate,
  endDate: show.endDate,
  show,
});

/**
 * A show's seasons as the library's cards, each on its own dates and wearing its own picture, so a
 * season stands on the shelf of the year it finished and one left open stands under In progress —
 * the same column that puts it under Currently Watching. Named and shelved as its show, so the
 * Franchise order shelves a season with its franchise, in the order the seasons were watched.
 *
 * `inScope` is the page's year scope read per season: the show filter keeps a show with any season
 * in the year, and every season of it drawn would put a show's other years on a wall scoped to one.
 */
export const seasonShelfItems = (item: ShowShelfItem, inScope?: (season: Season) => boolean): ShowShelfItem[] =>
  (inScope ? item.show.s.filter(inScope) : item.show.s).map((season) => ({
    ...item,
    artwork: seasonArtwork(season),
    startDate: season.startDate,
    endDate: season.endDate,
    season,
  }));

/** Every season of a show shares its name, so a season card is keyed as the union keys its row. */
export const shelfKey = (item: ShowShelfItem) => (item.season ? seasonKey(item.season) : finishedKey(item));

/** The library's second count: one card per season inside the year scope, where the page counts in shows. */
export const seasonSplit = (inScope?: (season: Season) => boolean): FinishedSplit<ShowShelfItem> => ({
  labels: ["Shows", "Seasons"],
  parts: (item) => seasonShelfItems(item, inScope),
  noun: "seasons",
});
